const e=[{id:"sv-1-941",phase:1,topic:"1.2.5",qtype:"concept",difficulty:3,stem:"A monthly report shows **DPU = 0.25** for installation work orders. What does this figure mean?",options:["On average, each work order carries 0.25 defects","25% of the work orders are defective","There are 0.25 defects per million opportunities","25% of the work orders pass right first time"],answer:0,hint:"DPU = defects shared over units — an average count, not a proportion of bad units.",steps:[{title:"Key idea",body:"Book glossary p. 585: DPU is total defects divided by total units. It is an **average number of defects per unit**."},{title:"Eliminate look-alikes",body:"Reading DPU as “% of units defective” is the classic trap: a single order may hold several defects."}],final:"DPU 0.25 = 0.25 defects per order on average → answer **A**",whyWrong:["","Incorrect — that is a % defective reading; DPU counts defects, and several can sit on one order.","Incorrect — a per-million figure is DPMO, which divides by opportunities, not units.","Incorrect — passing right first time is first time yield, a yield metric, not DPU."],trap:"DPU is not % defective — the numerators differ (defects vs defective units).",bookRef:"Book p. 585"},{id:"sv-1-942",phase:1,topic:"1.2.5",qtype:"concept",difficulty:1,stem:"Which describes **final yield** for a process step?",options:["The probability that a unit passes every step of the process with zero defects","The proportion of units that pass the step right first time, with no rework","The number of defects found divided by the number of units inspected","The proportion of units that are good at the end of the step, including units that were reworked"],answer:3,hint:"“Eventually good”, “after repair”, “shipped” → final yield.",steps:[{title:"Key idea",body:"Final yield counts units that are good **in the end**, so reworked units that later pass are included."},{title:"Eliminate look-alikes",body:"FTY excludes reworked units; RTY spans all steps; DPU counts defects."}],final:"Final yield = good at the end, rework included → answer **D**",whyWrong:["Incorrect — passing every step with zero defects is rolled throughput yield (RTY).","Incorrect — right first time with no rework is first time yield (FTY).","Incorrect — defects divided by units is DPU, a defect count, not a yield.",""],bookRef:"Syllabus 1.2.5"},{id:"sv-1-943",phase:1,topic:"1.2.5",qtype:"concept",difficulty:1,stem:"Why should an average **cycle time** always be reported with its time unit?",options:["Because sigma conversion tables need cycle time in seconds","Because the unit shows whether the figure is lead time or takt time","Because the same figure means very different things in hours, minutes or seconds","Because cycle time is a ratio with no unit and must be converted to a percentage"],answer:2,hint:"Convert to one time unit first, then label the answer.",steps:[{title:"Key idea",body:"Cycle time = net working time per unit completed. A result such as “1.25” is right only if labelled **hours** — 1.25 minutes is a different process."},{title:"Apply",body:"Stating the unit avoids misreading and mixed-unit errors such as treating 7 h 30 min as “7.30”."}],final:"Same number, different units → always state the unit → answer **C**",whyWrong:["Incorrect — sigma tables convert DPMO, not cycle time.","Incorrect — the unit does not identify which time metric is meant; each is defined by what it measures.","","Incorrect — cycle time is a time per unit, so it always has a time unit, unlike a yield."],bookRef:"Book p. 585"},{id:"sv-1-944",phase:1,topic:"1.2.5",qtype:"concept",difficulty:3,stem:"The book’s value stream map shows step yields of **0.92, 0.94, 0.59, 0.96 and 0.96** and an RTY of about **0.47**. What is the main lesson from this example?",options:["RTY of 0.47 means that 47% of units are scrapped","A stream with four steps above 0.90 will have an RTY close to 0.90","RTY is set by the last step of the stream, which here is 0.96","One weak step can drag the yield of the whole stream below 50%, even when the other steps are good"],answer:3,hint:"RTY = product of step yields; it is always ≤ the lowest step.",steps:[{title:"Read the example",body:"Four steps are at 0.92–0.96, yet the printed RTY is about 0.47."},{title:"Interpret",body:"The single 0.59 step is multiplied into the result and drags it below half (book p. 105)."}],final:"One weak step drags RTY down → answer **D**",whyWrong:["Incorrect — RTY is the share that passes every step first time; failures may be reworked, not scrapped.","Incorrect — RTY is a product, so the weak 0.59 step pulls it far below 0.90.","Incorrect — every step’s yield is multiplied in; the last step has no special weight.",""],bookRef:"Book p. 105"},{id:"sv-1-945",phase:1,topic:"1.2.5",qtype:"concept",difficulty:2,stem:"Which statement about a unit that is **scrapped** at a process step is CORRECT?",options:["It affects neither yield, because scrapped units leave the process","It lowers the first time yield but not the final yield","It lowers the final yield but not the first time yield","It lowers both the first time yield and the final yield of that step"],answer:3,hint:"FTY: rework and scrap fail. Final yield: rework that passes is good; scrap is never good.",steps:[{title:"Key idea",body:"Both yields divide by units **entering** the step. A scrapped unit never becomes good."},{title:"Apply",body:"So it is a failure for FTY and for final yield; only reworked-then-passed units separate the two."}],final:"Scrap lowers both yields → answer **D**",whyWrong:["Incorrect — scrapped units entered the step, so they stay in the denominator of both yields.","Incorrect — that describes a unit reworked and then passed; a scrapped unit is never good, so final yield falls too.","Incorrect — a scrapped unit did not pass first time, so FTY falls as well.",""],bookRef:"Syllabus 1.2.5"},{id:"sv-1-946",phase:1,topic:"1.2.5",qtype:"concept",difficulty:3,stem:"A plant adds a final inspection station that catches faulty units and sends them back for repair. Which statement about the effect on yield metrics is CORRECT?",options:["Final yield may rise, while the step first time yields and the RTY stay the same","RTY rises, because more faulty units are caught before shipping","All yields fall, because the inspection adds an extra step","First time yield rises at every step, because defects are found earlier"],answer:0,hint:"Inspection and repair change final yield, not right-first-time performance.",steps:[{title:"Key idea",body:"Final yield counts repaired units as good. FTY and RTY count only units right first time."},{title:"Apply",body:"Inspection plus repair hides more rework (the hidden factory): final yield can improve while FTY and RTY do not."}],final:"Final yield up; FTY and RTY unchanged → answer **A**",whyWrong:["","Incorrect — RTY uses first time yields; catching and repairing units does not make them pass first time.","Incorrect — repaired units count as good in final yield, so final yield can rise rather than fall.","Incorrect — defects are found at the end, after they were made; first-time performance of each step is unchanged."],trap:"Better final yield after adding inspection is not a quality improvement.",bookRef:"Book p. 588"},{id:"sv-1-947",phase:1,topic:"1.2.5",qtype:"statements",difficulty:2,stem:`Which statements about **DPU** are CORRECT?

1. DPU divides the defects by the total number of opportunities.
2. DPU can be greater than 1.
3. DPU uses the total number of units as its denominator.
4. DPU counts each defective unit only once, however many defects it has.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"DPU = total defects shared over total units.",steps:[{title:"Check each statement",body:"1 is false (that is DPO). 2 is true: twelve defects on eight routers give a DPU above 1. 3 is true. 4 is false (that is % defective)."},{title:"Match the pair",body:"The true statements are 2 and 3."}],final:"True statements are 2 and 3 → answer **B**",whyWrong:["Statement 1 is false: dividing by opportunities gives DPO or DPMO, not DPU.","","Statement 4 is false: DPU counts every defect; counting each bad unit once is % defective.","Statements 1 and 4 are both false: they describe DPO and % defective."],bookRef:"Book p. 585"},{id:"sv-1-948",phase:1,topic:"1.2.5",qtype:"not-except",difficulty:1,stem:"Each of the following is a **time-based** metric EXCEPT:",options:["Takt time","Defects per unit","Cycle time","Lead time"],answer:1,hint:"Times vs defect counts.",steps:[{title:"Key idea",body:"Cycle, lead and takt time are all measured in units of time."},{title:"Find the outsider",body:"Defects per unit is a defect-count metric with no time unit."}],final:"DPU is not a time metric → answer **B**",whyWrong:["Incorrect — takt time IS time-based: available time divided by customer demand.","","Incorrect — cycle time IS time-based: the time from start to completion of a task.","Incorrect — lead time IS time-based: the customer’s total wait including queues."],bookRef:"Syllabus 1.2.5"},{id:"sv-1-949",phase:1,topic:"1.2.5",qtype:"scenario",difficulty:2,stem:"A contact-centre Green Belt audits **200** recorded calls. Each call is scored against the same **8** checklist items, such as “greeting given” and “identity verified”, each marked pass or fail. In DPMO terms, what are the 8 checklist items?",options:["Defectives","Defects","Units","Opportunities"],answer:3,hint:"A characteristic of the unit judged acceptable or not = opportunity.",steps:[{title:"Key idea",body:"Book p. 587: an opportunity is a characteristic of the unit that can be classified as acceptable or unacceptable."},{title:"Apply",body:"Call = unit; checklist item = opportunity; failed item = defect; call with any fail = defective."}],final:"Pass/fail checklist items = opportunities → answer **D**",whyWrong:["Incorrect — a defective is a call with at least one failed item.","Incorrect — a defect is a failed checklist item, not the item itself.","Incorrect — the unit is the call; the checklist items are characteristics of each call.",""],bookRef:"Book p. 587"},{id:"sv-1-950",phase:1,topic:"1.2.5",qtype:"scenario",difficulty:2,stem:"A service-desk manager wants one figure for the share of tickets that the desk resolves **without the customer reopening them**. Reopened tickets are fixed later. Which metric fits this question?",options:["First time yield of the service-desk step","Rolled throughput yield of the whole support process","Defects per million opportunities","Final yield of the service-desk step"],answer:0,hint:"One step + right first time → FTY.",steps:[{title:"Key idea",body:"FTY is the share of units that pass a step right first time; reworked (reopened) units count as failures."},{title:"Apply",body:"A single step and “without reopening” point to FTY, not final yield or RTY."}],final:"One step, no reopening = FTY → answer **A**",whyWrong:["","Incorrect — RTY covers every step of the process, but the question is about the desk step only.","Incorrect — DPMO counts defects per opportunity; it is not the share of tickets resolved first time.","Incorrect — final yield counts reopened tickets that were later fixed as good, which hides the reopenings."],bookRef:"Syllabus 1.2.5"},{id:"sv-1-951",phase:1,topic:"1.2.5",qtype:"output",difficulty:2,stem:`A Black Belt prints a time summary for five fibre-installation jobs:

\`\`\`
Time summary: fibre installation jobs
Job   Queue before start (days)   Cycle time (h)   Lead time (days)
J1                 11                     4               11.2
J2                 15                     5               15.2
J3                  9                     3                9.1
J4                 18                     4               18.2
J5                 12                     6               12.3
\`\`\`

Which conclusion is supported by the output?`,options:["Lead time and cycle time are the same measure in different units","Cycle time is the main part of each job’s lead time","Almost all of each job’s lead time is queue time before work starts","Reducing cycle time to zero would remove most of the lead time"],answer:2,hint:"Lead time = queue + cycle time; compare the printed columns.",steps:[{title:"Read the output",body:"Queues are 9–18 days; cycle times are 3–6 hours; lead times are just above the queue values."},{title:"Interpret",body:"The customer’s wait is driven by queueing, not by the work itself."}],final:"Lead time is mostly queue time → answer **C**",whyWrong:["Incorrect — lead time includes the queue before work starts; cycle time does not.","Incorrect — cycle times are a few hours, while queues are 9–18 days.","","Incorrect — even with zero cycle time, the 9–18 day queues would remain."],bookRef:"Book p. 585"},{id:"sv-1-952",phase:1,topic:"1.2.5",qtype:"true-false",difficulty:1,stem:"For the same job, lead time is always at least as long as cycle time. True or False?",options:["True","False"],answer:0,hint:"Lead time = waiting + cycle time.",steps:[{title:"Key idea",body:"Cycle time runs from the start to the end of the work; lead time runs from the customer request to delivery."},{title:"Apply",body:"Lead time contains the cycle time, so it can never be shorter — the statement is true."}],final:"Lead time ≥ cycle time → answer **A** (True)",whyWrong:["","Incorrect — the statement is true: lead time contains the cycle time plus any waiting before or between work."],bookRef:"Book p. 585"},{id:"sv-1-953",phase:1,topic:"1.2.5",qtype:"sequence",difficulty:2,stem:`For a typical service job, arrange these times from **shortest** to **longest**:

- **P** Lead time
- **Q** Value-added time
- **R** Cycle time`,options:["P → R → Q","Q → P → R","R → Q → P","Q → R → P"],answer:3,hint:"Value-added time sits inside cycle time, which sits inside lead time.",steps:[{title:"Key idea",body:"Value-added time is the part of the work the customer pays for; cycle time is the whole task; lead time adds the waiting."},{title:"Order",body:"Value-added (Q) ≤ cycle (R) ≤ lead (P)."}],final:"VA → cycle → lead = Q → R → P → answer **D**",whyWrong:["Incorrect — this is longest to shortest, the reverse of what is asked.","Incorrect — lead time contains the cycle time plus waiting, so it is the longest.","Incorrect — value-added time is only part of the cycle time, so it cannot be longer than it.",""],bookRef:"Book p. 585"},{id:"sv-1-954",phase:1,topic:"1.2.5",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

The book glossary defines [?] as the total time from when a task, product or service is started until it is completed.`,options:["cycle time","lead time","takt time","wait time"],answer:0,hint:"Started → completed = cycle time.",steps:[{title:"Key idea",body:"Book glossary p. 585: **cycle time** is the total time from start to completion of a task, product or service."},{title:"Eliminate look-alikes",body:"Lead time adds the customer’s queue time; takt time is a demand-based pace; wait time is idle time only."}],final:"Start-to-completion time = cycle time → answer **A**",whyWrong:["","Incorrect — lead time is the customer’s total wait from request to delivery, including queues before work starts.","Incorrect — takt time is the available working time divided by customer demand.","Incorrect — wait time is the idle time between activities, only one part of lead time."],bookRef:"Book p. 585"},{id:"sv-1-955",phase:1,topic:"1.2.5",qtype:"best-action",difficulty:3,stem:"To speed up a baseline, a Black Belt measured the time from when each complaint entered the team’s queue until it was closed, and reported it to the Champion as the team’s **cycle time**. Was this an appropriate action?",options:["Yes, because cycle time should always include every queue the customer experiences","No, because that measure includes queue time before work starts, so it describes lead time","Yes, because cycle time and lead time are two names for the same measure","No, because cycle time can only be measured on manufactured products"],answer:1,hint:"Cycle time starts when the task is started; lead time starts when the customer request arrives.",steps:[{title:"Key idea",body:"Book p. 585: cycle time is from when a task is **started** until it is completed. Time sitting in a queue before work begins belongs to **lead time**."},{title:"Apply to the stem",body:"Entering the queue is not the start of work, so the measure is lead time and was labelled wrongly."}],final:"Queue entry → closure is lead time, so the label was wrong → answer **B**",whyWrong:["Incorrect — including every queue the customer experiences is the definition of lead time, not cycle time.","","Incorrect — they differ: cycle time runs from the start of work; lead time includes the waiting before it.","Incorrect — cycle time applies to any task, product or service, including complaint handling."],bookRef:"Book p. 585"},{id:"sv-1-956",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"What is a **project charter**?",options:["A detailed work plan that lists every task, owner and duration for the whole project","A hand-over document that tells the process owner how to sustain the gains","A document that records the verified root causes and the selected solutions","A one-page agreement between the team and its sponsor that records the business case, problem, goal, scope, team and milestones"],answer:3,hint:"Charter = the short, signed Define agreement on why, what, how far and who.",steps:[{title:"Key idea",body:"The charter is normally one page and is signed by the Champion. It holds the business case, problem and goal statements, scope, milestones and team."},{title:"Eliminate look-alikes",body:"Task plans, root-cause records and control plans are other project documents produced later or in more detail."}],final:"Charter = one-page team–sponsor agreement → answer **D**",whyWrong:["Incorrect — a task-level work plan is a project schedule; the charter is a short agreement on why, what and how far.","Incorrect — sustaining the gains is the job of the control plan in the Control phase.","Incorrect — verified causes and solutions come from Analyze and Improve, long after the charter is signed.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-957",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Who is the main **audience** of the business case in a project charter?",options:["Leadership and Finance, who decide whether the problem deserves resources","External customers, who receive a copy to show the company cares","Front-line operators, who will carry out the new process steps","Vendor engineers, who must agree the root cause before the project starts"],answer:0,hint:"Business case = the argument for spending scarce people and money.",steps:[{title:"Key idea",body:"The business case answers the leadership question “why this, why now?” and carries the early COPQ estimate."},{title:"Apply",body:"Its readers are the leaders and Finance staff who approve and fund the project."}],final:"Audience = leadership and Finance → answer **A**",whyWrong:["","Incorrect — the business case is an internal document; customers’ needs are an input to it (VOC).","Incorrect — operators are trained on the new process in Improve and Control; the business case is a funding argument.","Incorrect — root causes are verified in Analyze; the business case argues why the problem matters now."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-958",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which is a purpose of the **goal statement** in a project charter?",options:["To state the measurable result the project will achieve and the date it will be achieved","To explain why the problem matters to the business strategy now","To list the people who must be informed or consulted during the project","To describe how the team will change the process to reach the target"],answer:0,hint:"Goal = metric + target + date.",steps:[{title:"Key idea",body:"The goal (objective) statement mirrors the problem statement: same metric, plus a target and a completion date."},{title:"Eliminate look-alikes",body:"Why-now is the business case; the method comes later; stakeholders have their own section."}],final:"Goal statement = measurable result + date → answer **A**",whyWrong:["","Incorrect — the strategic link and urgency belong to the business case.","Incorrect — people to inform or consult are listed in the stakeholder section.","Incorrect — the method is discovered in Analyze and Improve; the goal says what, not how."],bookRef:"Book p. 587"},{id:"sv-1-959",phase:1,topic:"1.3.1",qtype:"concept",difficulty:3,stem:"According to the book glossary, how is a **Six Sigma project** described?",options:["A problem stated in quantifiable terms and with known improvement expectations","A company-wide change programme that covers all processes at once","Any improvement idea raised by an employee through the suggestion scheme","A task whose solution is already known and only needs to be implemented"],answer:0,hint:"Book p. 589: quantifiable terms + known improvement expectations.",steps:[{title:"Key idea",body:"The glossary (p. 589) describes a Six Sigma project as a problem stated **in quantifiable terms** and **with known improvement expectations**."},{title:"Eliminate look-alikes",body:"Known solutions, raw ideas and company-wide programmes all lack the quantified, bounded problem."}],final:"Quantified problem + known improvement expectations → answer **A**",whyWrong:["","Incorrect — an all-processes programme is a deployment, not a single bounded project.","Incorrect — an idea becomes a project only when the problem is quantified and expectations are set.","Incorrect — a problem with a known fix is a “just do it” action, not a Six Sigma project."],bookRef:"Book p. 589"},{id:"sv-1-960",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"What is a **disguised solution** in a draft problem statement?",options:["A statement that sounds like a problem but already names the fix, such as “we lack an auto-routing tool”","A root cause that is hidden in the data and found only in Analyze","A solution that is piloted in one area before being rolled out","A quick win that the team implements during the Measure phase"],answer:0,hint:"Warning words: lack of, need to, insufficient, should implement, a named tool or headcount.",steps:[{title:"Key idea",body:"A disguised solution states the answer as if it were the problem (“we lack…”, “we need to…”)."},{title:"Why it matters",body:"It skips Measure and Analyze: the team builds the named fix even if the real cause is different."}],final:"Disguised solution = the fix written as the problem → answer **A**",whyWrong:["","Incorrect — a hidden cause is an X still to be discovered, not a wording fault in the problem statement.","Incorrect — a small-scale trial is a pilot, an Improve-phase activity.","Incorrect — a quick win is an early, low-risk fix, not a fault in the problem wording."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-961",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Why should the goal statement use the **same metric** as the problem statement?",options:["So that the project can claim savings without validation by Finance","So that success can be judged directly against the baseline stated in the problem","So that the Champion does not need to sign the goal separately","So that the team can skip collecting a new baseline in Measure"],answer:1,hint:"Problem gives the baseline; goal gives the target — same yardstick.",steps:[{title:"Key idea",body:"The problem statement sets the baseline (e.g. 18% late). The goal must use the same metric and units (e.g. 6% late by a date)."},{title:"Apply",body:"With different metrics nobody can tell whether the project succeeded — a common charter mistake."}],final:"Same metric → success measurable against baseline → answer **B**",whyWrong:["Incorrect — benefits always need validation; using the same metric does not remove that step.","","Incorrect — the Champion signs the whole charter; the metric choice has nothing to do with signatures.","Incorrect — Measure still confirms the baseline; the matching metric is about judging success."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-962",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"How is the **SMART** test applied to a draft goal statement?",options:["By checking it ranks the project risks by likelihood and impact","By checking it lists the solutions the team will implement and their costs","By checking it assigns each DMAIC task to a named team member","By checking it names one metric, has a baseline and target, is realistic, supports the business case and has a date"],answer:3,hint:"Specific, Measurable, Achievable, Relevant, Time-bound.",steps:[{title:"Key idea",body:"SMART = **S**pecific, **M**easurable, **A**chievable, **R**elevant, **T**ime-bound."},{title:"Apply",body:"Each letter becomes a check on the goal wording: one metric, a number with baseline and target, realistic, linked to the business case, dated."}],final:"SMART checks the goal wording itself → answer **D**",whyWrong:["Incorrect — ranking risks is risk management, not a test of the goal wording.","Incorrect — solutions and costs are not part of a SMART goal; the goal says what, not how.","Incorrect — task assignment is project planning, not a test of the goal statement.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-963",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"In a SMART goal statement, what does **Relevant** require?",options:["That the goal is realistic for the team, budget and time available","That the goal states a number with a baseline and a target","That the goal includes a completion date","That reaching the goal moves the business case or strategic objective the project was launched for"],answer:3,hint:"Relevant = linked to why the project exists.",steps:[{title:"Key idea",body:"A goal is **Relevant** when it moves the business case — not a side issue the sponsor does not care about."},{title:"Eliminate look-alikes",body:"Each wrong option describes another SMART letter: Measurable, Time-bound, Achievable."}],final:"Relevant = supports the business case → answer **D**",whyWrong:["Incorrect — being realistic for the resources is the Achievable requirement.","Incorrect — a number with baseline and target is the Measurable requirement.","Incorrect — a completion date is the Time-bound requirement.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-964",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which describes the role of **subject-matter experts** named in a Black Belt project charter?",options:["They own the process day to day and receive the improved process at hand-over","They provide specialist process or technical knowledge to the team, often part-time when needed","They sign the charter and are accountable for the business result","They lead the project and run the DMAIC tollgate reviews"],answer:1,hint:"Champion = accountable; process owner = owns the process; Belt = leads; SMEs = specialist knowledge.",steps:[{title:"Key idea",body:"Subject-matter experts bring specialist knowledge (systems, engineering, policy) when the team needs it; they do not own the result."},{title:"Eliminate look-alikes",body:"Accountability, process ownership and project leadership belong to other named roles."}],final:"SMEs = specialist knowledge on call → answer **B**",whyWrong:["Incorrect — running the process and receiving it at hand-over is the process owner’s role.","","Incorrect — signing and accountability for the result belong to the Champion (sponsor).","Incorrect — leading the project is the Black Belt’s role; the Champion chairs the tollgate decisions."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-965",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"What is the role of the **process owner** named in a project charter?",options:["The leader who sponsors the project, signs the charter and removes barriers","The manager who runs the process day to day and will own the improved process after hand-over","The coach who mentors the Black Belt on statistical tools","The analyst who confirms the financial benefits at project closure"],answer:1,hint:"Who lives with the process after the project? → process owner.",steps:[{title:"Key idea",body:"The process owner manages the process and must accept and sustain the improved process in Control."},{title:"Eliminate look-alikes",body:"Champion = sponsor; MBB/BB = coach; Finance = benefit validation."}],final:"Process owner = owns and sustains the process → answer **B**",whyWrong:["Incorrect — sponsoring, signing and removing barriers is the Champion’s role.","","Incorrect — coaching on tools is normally the Black Belt or Master Black Belt role.","Incorrect — confirming benefits is done by the Finance representative."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-966",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which describes a DMAIC **tollgate**?",options:["A statistical test that checks whether a solution has a significant effect","A daily stand-up meeting where team members report tasks completed","A limit on the project budget that cannot be exceeded","A formal review at the end of a phase where the Champion decides whether the project may move on"],answer:3,hint:"Tollgate = phase-end gate review with a go / no-go decision.",steps:[{title:"Key idea",body:"At each tollgate the team presents the phase deliverables and the Champion decides go, no-go or rework."},{title:"Link to the charter",body:"The charter is reviewed and re-confirmed at these reviews."}],final:"Tollgate = phase-end Champion review → answer **D**",whyWrong:["Incorrect — testing significance is hypothesis testing, used in Analyze and Improve.","Incorrect — a daily stand-up is a team routine, not a formal phase-end decision point.","Incorrect — a fixed budget limit is a constraint recorded in the charter.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-967",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"What is the purpose of the **milestones** section of a project charter?",options:["To list the uncertain events that could delay the project","To record the estimated financial benefits of the project","To define the process start and end points","To set target dates for completing each DMAIC phase and its tollgate"],answer:3,hint:"Milestones = when each phase / tollgate is due.",steps:[{title:"Key idea",body:"Milestones give the timeline: a target date per DMAIC phase, reviewed at each tollgate."},{title:"Eliminate look-alikes",body:"Risks, scope and benefits are other charter elements."}],final:"Milestones = tollgate target dates → answer **D**",whyWrong:["Incorrect — uncertain events are risks, recorded in the risks section.","Incorrect — estimated benefits have their own preliminary-benefits section.","Incorrect — start and end points belong to the scope section.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-968",phase:1,topic:"1.3.1",qtype:"concept",difficulty:3,stem:"A charter lists: *“Incident priority codes are applied consistently by all NOC shifts.”* How should the team handle this **assumption**?",options:["By respecting it as a fixed limit the project cannot change","By escalating it to the Champion as an issue that has already occurred","By checking it with data early, because it is treated as true without proof","By preparing a mitigation plan in case the event happens"],answer:2,hint:"Risk → mitigate; assumption → verify; constraint → respect.",steps:[{title:"Key idea",body:"An **assumption** is taken as true without proof, so it must be **checked** — if priority codes are not consistent, the data are not trustworthy."},{title:"Eliminate look-alikes",body:"Risks are mitigated, constraints respected and issues resolved."}],final:"Assumption → verify with data → answer **C**",whyWrong:["Incorrect — a fixed limit is a constraint, not an assumption.","Incorrect — something that has already happened is an issue, not an assumption.","","Incorrect — mitigation plans are for risks, which are uncertain future events."],trap:"Risk, assumption and constraint are the classic charter look-alikes.",bookRef:"Syllabus 1.3.1"},{id:"sv-1-969",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Why are the benefits in a Define-phase charter labelled **preliminary**?",options:["They are copied from the vendor’s proposal and never revisited","They are estimates that will be refined with data and validated with Finance before they are claimed","They are confirmed savings that only need the Champion’s signature","They are hidden from the team so that targets are not influenced"],answer:1,hint:"Define benefits = estimates; validation comes later with Finance.",steps:[{title:"Key idea",body:"At Define the team has only rough data, so the benefit is an **estimate**. It is refined in Measure and validated with Finance before anyone claims it."},{title:"Apply",body:"Stating benefits as fact before validation is a common charter mistake."}],final:"Preliminary = estimated, not yet validated → answer **B**",whyWrong:["Incorrect — benefits are revisited in Measure and validated with Finance, not left unchanged.","","Incorrect — in Define no data have been validated, so the benefits cannot be confirmed savings.","Incorrect — benefits are visible on the charter; “preliminary” refers to their uncertainty."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-970",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which charter element records the people or groups who are affected by the project and must be **informed or consulted**?",options:["Scope","Stakeholders","Milestones","Constraints"],answer:1,hint:"Who is affected / must be kept informed → stakeholders.",steps:[{title:"Key idea",body:"The stakeholder list names who is affected and who must be informed or consulted, even if they do no project work."},{title:"Eliminate look-alikes",body:"Milestones, scope and constraints answer when, where and within what limits."}],final:"Inform / consult → stakeholders → answer **B**",whyWrong:["Incorrect — scope sets the process boundaries, not the people to inform.","","Incorrect — milestones are target dates for each DMAIC phase.","Incorrect — constraints are fixed limits the project must work within."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-971",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"When is the project charter normally **signed** by the Champion?",options:["At the end of Improve, once the solution has been piloted","At the end of Measure, once the baseline has been confirmed","At the end of Define, before the team starts the Measure phase","At project closure, when Finance validates the benefits"],answer:2,hint:"No signature → no committed sponsor, scope or resources.",steps:[{title:"Key idea",body:"The charter is drafted in Define and signed at the Define tollgate so the team starts Measure with an agreed problem, scope and sponsor."},{title:"Living document",body:"It is then reviewed and re-confirmed at later tollgates."}],final:"Signed at the Define tollgate → answer **C**",whyWrong:["Incorrect — waiting until Improve would leave most of the project without an agreed scope or sponsor.","Incorrect — the charter is reviewed in Measure, but the team needs a signed charter to start Measure.","","Incorrect — closure is when results are checked against the charter, not when it is first signed."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-972",phase:1,topic:"1.3.1",qtype:"concept",difficulty:3,stem:"In **Y = f(X)** terms, what does the problem statement of a charter describe?",options:["Both the Y and the X’s, so the team can start on the solution","The f — the solution that will change the relationship","The X’s — the verified causes that drive the problem","The Y — the output gap the customer or business sees; the X’s are found later"],answer:3,hint:"Define describes the Y; Measure and Analyze find the X’s.",steps:[{title:"Key idea",body:"The problem statement describes the symptom (the Y): what, where, when, how big, impact."},{title:"Apply",body:"Finding the X’s that drive the Y is the work of Measure and Analyze, so no cause belongs in Define."}],final:"Problem statement = the Y only → answer **D**",whyWrong:["Incorrect — the problem statement must contain no cause, so it describes only the Y.","Incorrect — the solution belongs to Improve; naming it in Define is a disguised solution.","Incorrect — causes are verified in Analyze; putting X’s in the problem statement is a stated cause.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-973",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"A draft problem statement reads: *“Customers are unhappy with our billing.”* What is its main weakness?",options:["It blames a named team for the problem","It states a cause that has not yet been verified","It names a solution that the team has already chosen","It gives no measure, location or time frame, so the size of the problem is unknown"],answer:3,hint:"A problem statement needs what, where, when, how big and impact.",steps:[{title:"Key idea",body:"A good problem statement is bounded and quantified: what, where, when, how big, impact."},{title:"Apply",body:"“Customers are unhappy” has no metric, no segment, no period and no size, so it cannot be baselined."}],final:"Vague: not quantified or bounded → answer **D**",whyWrong:["Incorrect — no person or team is blamed; the fault is vagueness.","Incorrect — no cause appears; the statement simply lacks what, where, when and how big.","Incorrect — no fix is named; the fault is that nothing is quantified or bounded.",""],bookRef:"Book p. 587"},{id:"sv-1-974",phase:1,topic:"1.3.1",qtype:"concept",difficulty:3,stem:"A Black Belt is unsure whether an activity belongs in the Define phase. Which question is a useful test?",options:["“Does this help sustain the gains after hand-over?”","“Does this help launch and scope the project?”","“Does this verify the root cause of the problem?”","“Does this prove the solution works on a small scale?”"],answer:1,hint:"Define = launch and scope the project.",steps:[{title:"Key idea",body:"Define work launches and scopes the project: charter, business case, scope, team, VOC."},{title:"Eliminate look-alikes",body:"Root-cause verification, piloting and sustaining belong to Analyze, Improve and Control."}],final:"Define test: launch and scope → answer **B**",whyWrong:["Incorrect — sustaining gains is the purpose of Control.","","Incorrect — verifying root causes is the test for Analyze work, not Define.","Incorrect — proving a solution on a small scale is piloting, an Improve activity."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-975",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"What is the main purpose of the **problem statement** in a project charter?",options:["To state the target value and completion date","To describe what is wrong, where, since when, how big and with what impact","To name the solution that the sponsor has requested","To argue why the organisation should fund the project now"],answer:1,hint:"Problem statement = the measurable gap, bounded in time and place.",steps:[{title:"Key idea",body:"Book p. 587: a problem statement succinctly bounds and describes the business problem — what, where, when, how big, impact."},{title:"Eliminate look-alikes",body:"Why-now is the business case; target and date are the goal; solutions do not belong."}],final:"Problem statement = bounded description of the gap → answer **B**",whyWrong:["Incorrect — target and date belong to the goal statement.","","Incorrect — naming a solution in the problem statement is the disguised-solution mistake.","Incorrect — the funding argument and urgency belong to the business case."],bookRef:"Book p. 587"},{id:"sv-1-976",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which describes a well-defined **scope boundary** for a billing-dispute project?",options:["The billing team and its managers","The billing platform and its servers","All billing activities across the company","Enterprise invoices from bill run to dispute closure"],answer:3,hint:"Scope = a process with a clear start and end point (plus in / out lists).",steps:[{title:"Key idea",body:"Scope is defined as a **process** with a clear start and end point, then made explicit with in-scope and out-of-scope lists."},{title:"Apply",body:"Only “bill run → dispute closure” for enterprise invoices gives both a segment and process boundaries."}],final:"Process start + end point = good scope → answer **D**",whyWrong:["Incorrect — a team is an organisation unit, not a process with start and end points.","Incorrect — a system is not a process boundary; scope is set on the process.","Incorrect — “all activities” has no start or end point and invites boil-the-ocean scope.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-977",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which describes the **impact** element of a problem statement?",options:["The consequence of the gap for the customer or business, such as service credits or escalations","The region or customer segment in which the problem occurs","The time window over which the problem was observed","The number or percentage of units affected"],answer:0,hint:"What, where, when, how big — and so what? (impact).",steps:[{title:"Key idea",body:"Impact answers “so what?” — the cost, penalty, risk or customer effect caused by the gap."},{title:"Eliminate look-alikes",body:"Where, when and how big are the other elements of the five-part statement."}],final:"Impact = consequence for customer / business → answer **A**",whyWrong:["","Incorrect — the region or segment is the “where” element.","Incorrect — the time window is the “when” element.","Incorrect — the count or percentage is the “how big” element."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-978",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"A sponsor sets the goal: *“Eliminate all late restorations within one month,”* with no extra people or budget. Which SMART element is **weakest**?",options:["Relevant","Measurable","Achievable","Time-bound"],answer:2,hint:"Realistic for the team, budget and time → Achievable.",steps:[{title:"Key idea",body:"Achievable means ambitious but realistic for the team, budget and time available."},{title:"Apply",body:"Zero late restorations in one month with no resources is not realistic; the other letters are present."}],final:"Unrealistic target → fails Achievable → answer **C**",whyWrong:["Incorrect — late restorations are clearly linked to the business case.","Incorrect — “all late restorations” to zero is a number that can be measured.","","Incorrect — “within one month” gives a time limit."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-979",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"In which DMAIC phase is the project charter **first drafted**?",options:["Analyze","Define","Control","Measure"],answer:1,hint:"Charter = Define deliverable.",steps:[{title:"Key idea",body:"The charter is the main Define deliverable: it launches and scopes the project."},{title:"Living document",body:"Later phases review and update it at tollgates."}],final:"Charter first drafted in Define → answer **B**",whyWrong:["Incorrect — Analyze verifies root causes; by then the charter has been in use for two phases.","","Incorrect — Control checks results against the charter; it does not create it.","Incorrect — Measure reviews and may refine the charter, but it is drafted before Measure starts."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-980",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which is an example of **Voice of the Business** evidence for a project’s business case?",options:["A three-quarter rise in SLA service-credit payments to enterprise customers","Verbatim complaints from customers about slow repairs","Engineers’ survey comments about workload and tools","A vendor brochure describing a new monitoring tool"],answer:0,hint:"VOB = the business’s own financial and performance needs.",steps:[{title:"Key idea",body:"Voice of the Business is evidence about cost, revenue, risk and performance from the business’s point of view."},{title:"Apply",body:"Rising service-credit payments are a financial loss to the business, so they are VOB."}],final:"Service-credit cost trend = VOB → answer **A**",whyWrong:["","Incorrect — customers’ own words are Voice of the Customer evidence.","Incorrect — employees’ views are Voice of the Employee evidence.","Incorrect — a product brochure is a possible solution, not evidence of business pain."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-981",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the **problem statement** in a project charter is CORRECT?",options:["It should include the planned solution and its expected cost","It describes the gap in measurable terms without naming a cause","It is written at the end of Analyze, once the causes are known","It should name the most likely root cause so the team can focus quickly"],answer:1,hint:"No cause, no solution, no blame.",steps:[{title:"Key idea",body:"A problem statement describes what, where, when, how big and impact — and contains no cause, no solution and no blame."},{title:"Eliminate look-alikes",body:"Causes, solutions and late timing all break that rule."}],final:"Measurable gap, no cause → answer **B**",whyWrong:["Incorrect — a planned solution in the problem statement is a disguised solution.","","Incorrect — the problem statement is written in Define, before any causes are studied.","Incorrect — causes are verified in Analyze; naming one in Define is a red-flag mistake."],bookRef:"Book p. 587"},{id:"sv-1-982",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the **goal statement** is CORRECT?",options:["It states what result will be achieved and by when, but not how","It may use a different metric from the problem statement if that is easier to collect","It is written by Finance after the benefits have been validated","It describes the method the team will use to reach the target"],answer:0,hint:"Goal = what + by when; never how.",steps:[{title:"Key idea",body:"The book’s objective statement gives goals, timing and expectations (p. 587). It mirrors the problem metric and adds a target and date."},{title:"Eliminate look-alikes",body:"Methods, different metrics and Finance authorship are all charter mistakes."}],final:"Goal says what and when, not how → answer **A**",whyWrong:["","Incorrect — a different metric means success cannot be judged against the baseline.","Incorrect — the goal is written by the team in Define and agreed with the Champion.","Incorrect — the method is discovered in Analyze and Improve; the goal states only the result."],bookRef:"Book p. 587"},{id:"sv-1-983",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the **Specific** element of a SMART goal is CORRECT?",options:["It requires the goal to include a completion date","It requires the goal to describe the specific solution to be implemented","It requires one clearly named metric and population, such as P1/P2 enterprise incidents in the North","It requires the target to be realistic for the team and budget"],answer:2,hint:"Specific = which metric, for which population.",steps:[{title:"Key idea",body:"A **Specific** goal names exactly what is measured and for whom, so nobody can read it two ways."},{title:"Eliminate look-alikes",body:"Dates are Time-bound, realism is Achievable, and solutions never belong in the goal."}],final:"Specific = one named metric and population → answer **C**",whyWrong:["Incorrect — a completion date is the Time-bound element.","Incorrect — a goal never names the solution; Specific refers to the metric and population.","","Incorrect — being realistic for the resources is the Achievable element."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-984",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which statement about the **scope** section of a charter is CORRECT?",options:["It is set by the team alone and does not need the Champion’s agreement","It defines the process start and end points and lists what is in and out of scope","It lists only what is in scope, because anything not listed is out","It should be as wide as possible to maximise the project benefits"],answer:1,hint:"Scope = process boundaries + explicit in / out lists, agreed with the Champion.",steps:[{title:"Key idea",body:"Scope draws the fence: a process with a start and an end, then explicit in-scope and out-of-scope lists."},{title:"Eliminate look-alikes",body:"Implicit exclusions, team-only decisions and maximal scope are common mistakes."}],final:"Start/end points + in/out lists → answer **B**",whyWrong:["Incorrect — scope is part of the signed charter and any change is a Champion decision.","","Incorrect — an explicit out-of-scope list is needed; silence invites scope creep.","Incorrect — a wide scope dilutes effort and delays the finish (boil-the-ocean)."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-985",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which statement about a project **risk** listed in the charter is CORRECT?",options:["It is an uncertain event that could hurt the project and needs a mitigation","It is a problem that has already happened and must be resolved now","It is something treated as true without proof that should be checked","It is a fixed limit, such as no new headcount, that the project must respect"],answer:0,hint:"Risk = might happen → mitigate.",steps:[{title:"Key idea",body:"A **risk** is uncertain: *the vendor may not release data in time*. It needs a mitigation plan."},{title:"Eliminate look-alikes",body:"Constraints are fixed limits, assumptions need checking, and issues have already happened."}],final:"Risk = uncertain event → mitigation → answer **A**",whyWrong:["","Incorrect — an event that has already occurred is an issue, not a risk.","Incorrect — something taken as true without proof is an assumption.","Incorrect — a fixed limit the project must respect is a constraint."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-986",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the **Champion** and the **Green Belt** is CORRECT?",options:["The Champion joins the project only at the Control tollgate","The Champion is accountable for the business result; the Black Belt leads the project work","The Black Belt is accountable for the business result; the Champion leads the project work","The Champion and the Black Belt share the data collection equally"],answer:1,hint:"Champion = accountable sponsor; Belt = project leader.",steps:[{title:"Key idea",body:"The Champion owns the result, signs the charter, provides resources and removes barriers. The Black Belt leads the team through DMAIC."},{title:"Eliminate look-alikes",body:"Swapped roles, shared data collection and a late-joining Champion are all wrong."}],final:"Champion accountable; Belt leads → answer **B**",whyWrong:["Incorrect — the Champion signs the charter in Define and reviews every tollgate.","","Incorrect — the roles are swapped: the Champion owns the result and the Belt leads the work.","Incorrect — data collection is team work led by the Belt; the Champion provides resources and removes barriers."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-987",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which statement about choosing a problem for a **DMAIC project** is CORRECT?",options:["A DMAIC project suits a problem whose root cause is not yet known","A DMAIC project suits a problem for which no data can be collected","A DMAIC project suits a problem whose solution is known and only needs implementing","A DMAIC project should cover the whole organisation to maximise benefit"],answer:0,hint:"Unknown cause + measurable problem + bounded scope → DMAIC.",steps:[{title:"Key idea",body:"DMAIC is worth its effort when the cause is unknown: Measure and Analyze exist to find it."},{title:"Eliminate look-alikes",body:"Known fixes, unmeasurable problems and company-wide scope are poor DMAIC candidates."}],final:"Unknown root cause → DMAIC → answer **A**",whyWrong:["","Incorrect — DMAIC depends on data; a problem with no measurable output cannot be baselined.","Incorrect — a problem with a known solution is a “just do it” action.","Incorrect — DMAIC projects are bounded; company-wide scope is boil-the-ocean."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-988",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"Which statement about the **length** of a project charter is CORRECT?",options:["The length of a charter does not matter as long as the Champion signs it","If a project cannot be described on one page, it is probably too big or not yet understood","A charter should be long enough to list every task in the project plan","A charter must be at least five pages so that Finance will accept it"],answer:1,hint:"One page is a feature, not a limitation.",steps:[{title:"Key idea",body:"A charter is normally a single page. Needing more usually means the project is too big or the problem is not yet understood."},{title:"Eliminate look-alikes",body:"Task lists, minimum lengths and “length does not matter” miss the point of the one-page rule."}],final:"One page → right-sized, understood project → answer **B**",whyWrong:["Incorrect — length is a warning sign: an over-long charter suggests a project that is too big.","","Incorrect — the task list belongs to the project plan; the charter is a short agreement.","Incorrect — there is no minimum length; brevity is a feature of the charter."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-989",phase:1,topic:"1.3.1",qtype:"concept",difficulty:3,stem:"Why should a charter’s problem statement contain **no blame**?",options:["Blame makes the problem statement too short to be signed","Blame belongs in the business case instead of the problem statement","Blame asserts an unverified cause and makes the people involved defensive about the data","Blame is only allowed once the Measure baseline is confirmed"],answer:2,hint:"No cause, no solution, no blame.",steps:[{title:"Key idea",body:"“The vendor’s engineers are careless” is both blame and an unverified cause. It skips Analyze and turns data conversations into arguments."},{title:"Apply",body:"A neutral, data-based gap keeps everyone focused on the facts."}],final:"Blame = unverified cause + defensiveness → answer **C**",whyWrong:["Incorrect — length is not the issue; blame is a stated cause that has not been verified.","Incorrect — the business case argues why the problem matters; it does not assign fault either.","","Incorrect — blame never belongs in the problem statement, at any phase."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-990",phase:1,topic:"1.3.1",qtype:"statements",difficulty:1,stem:`Which statements describe elements of a good **problem statement**?

1. It states the time window in which the problem was observed.
2. It states the size of the gap, for example a count or a percentage.
3. It states the most likely cause of the gap.
4. It states the solution the sponsor prefers.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"What, where, when, how big, impact — no cause, no solution.",steps:[{title:"Check each statement",body:"1 (when) and 2 (how big) are elements of the five-part model. 3 (cause) and 4 (solution) are the two classic faults."},{title:"Match the pair",body:"Only 1 and 2 are correct."}],final:"Time window + size of gap → 1 and 2 → answer **A**",whyWrong:["","Statement 3 is wrong: a cause has not been verified in Define and does not belong in the problem statement.","Statements 3 and 4 are both wrong: causes and solutions are excluded from a problem statement.","Statement 4 is wrong: a preferred solution in the problem statement is a disguised solution."],bookRef:"Book p. 587"},{id:"sv-1-991",phase:1,topic:"1.3.1",qtype:"statements",difficulty:2,stem:`Which two items are normal elements of a Lean Six Sigma **project charter**?

1. The verified root cause of the problem.
2. The in-scope and out-of-scope boundaries.
3. The milestone dates for each DMAIC tollgate.
4. The control plan for the improved process.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Charter = Define items only: case, problem, goal, scope, milestones, team.",steps:[{title:"Check each item",body:"Scope (2) and milestones (3) are charter elements. A verified root cause (1) comes from Analyze; a control plan (4) from Control."},{title:"Match the pair",body:"The correct pair is 2 and 3."}],final:"Scope + milestones → 2 and 3 → answer **B**",whyWrong:["Statement 1 is wrong: a verified root cause is an Analyze output, not a Define charter element.","","Statement 4 is wrong: the control plan is a Control-phase deliverable.","Statements 1 and 4 are both outputs of later phases (Analyze and Control)."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-992",phase:1,topic:"1.3.1",qtype:"statements",difficulty:2,stem:`Which statements about the **business case** are CORRECT?

1. It is a detailed technical design of the chosen solution.
2. It is written to justify a solution the sponsor has already chosen.
3. It explains why the problem must be tackled now.
4. It shows how the project links to a strategic objective or KPI.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Why this, why now, cost of doing nothing, link to strategy.",steps:[{title:"Check each statement",body:"1 and 2 turn the business case into a solution document — wrong. 3 (why now) and 4 (strategic link) are two of its four questions."},{title:"Match the pair",body:"The correct pair is 3 and 4."}],final:"Why now + strategic link → 3 and 4 → answer **C**",whyWrong:["Statements 1 and 2 are wrong: the business case proposes no fix and is not a sales pitch for one.","Statement 2 is wrong: a business case argues for tackling a problem, not for a pre-chosen solution.","","Statement 1 is wrong: a detailed technical design is not part of a business case."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-993",phase:1,topic:"1.3.1",qtype:"statements",difficulty:3,stem:`Which statements about **scope creep** are CORRECT?

1. It is the gradual, unapproved growth of a project beyond its chartered boundaries.
2. It can be prevented by never changing the charter after it is signed.
3. It should be welcomed because each addition increases the benefits.
4. Its usual effect is diluted team effort and a delayed finish.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Scope creep = unapproved growth; it dilutes effort and delays the finish.",steps:[{title:"Check each statement",body:"1 is the definition — true. 2 is false: the charter is a living document. 3 is false: creep harms the project. 4 is true."},{title:"Match the pair",body:"The correct pair is 1 and 4."}],final:"Definition + effect → 1 and 4 → answer **D**",whyWrong:["Statement 2 is wrong: charters can change; the defence is a formal Champion decision, not a frozen charter.","Statements 2 and 3 are both wrong: freezing the charter is not the remedy, and creep is harmful, not welcome.","Statement 3 is wrong: small additions together dilute effort and push back the finish line.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-994",phase:1,topic:"1.3.1",qtype:"statements",difficulty:2,stem:`Which statements describe a **SMART** goal statement?

1. It names how the improvement will be achieved.
2. It has a baseline and a target in the same metric as the problem.
3. It has a completion date.
4. It covers all products and regions to maximise the benefit.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Specific, Measurable, Achievable, Relevant, Time-bound.",steps:[{title:"Check each statement",body:"2 meets Measurable and 3 meets Time-bound. 1 adds the method; 4 breaks Specific and Achievable."},{title:"Match the pair",body:"The correct pair is 2 and 3."}],final:"Baseline + target + date → 2 and 3 → answer **B**",whyWrong:["Statement 1 is wrong: a goal says what and by when, not how.","","Statement 4 is wrong: covering everything breaks Specific and Achievable.","Statements 1 and 4 are both wrong: the method and an unbounded scope are not part of a SMART goal."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-995",phase:1,topic:"1.3.1",qtype:"statements",difficulty:3,stem:`A Black Belt reviews four draft problem statements. Which drafts are **disguised solutions**?

1. “We lack a self-service portal for bill disputes.”
2. “Field teams need more training on fibre splicing.”
3. “In FY2025, 9% of supplier invoices were paid after the due date.”
4. “Since March, 31% of P2 tickets waited more than 45 minutes for assignment.”`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Warning words: lack of, need to/needs, a named tool, training or headcount.",steps:[{title:"Check each draft",body:"1 (“lack a portal”) and 2 (“need more training”) both name a fix. 3 and 4 describe measured gaps."},{title:"Match the pair",body:"The disguised solutions are 1 and 2."}],final:"Portal + training drafts → 1 and 2 → answer **A**",whyWrong:["","Statement 3 is a sound problem statement: it states a measured gap with a time frame and no fix.","Statements 3 and 4 are both sound problem statements with data, time frames and no solution.","Statement 4 is a sound problem statement: it gives a measured gap against a time window."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-996",phase:1,topic:"1.3.1",qtype:"statements",difficulty:2,stem:`Which statements describe responsibilities of the **Champion** in a Black Belt project?

1. Signing the project charter.
2. Collecting the measurement data.
3. Running the hypothesis tests in Analyze.
4. Removing barriers that block the team.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Champion: signs, resources, removes barriers, decides at tollgates.",steps:[{title:"Check each statement",body:"1 (sign the charter) and 4 (remove barriers) are Champion duties. 2 and 3 are hands-on project work."},{title:"Match the pair",body:"The correct pair is 1 and 4."}],final:"Sign + remove barriers → 1 and 4 → answer **D**",whyWrong:["Statement 2 is wrong: data collection is done by the team under the Black Belt.","Statements 2 and 3 are both team tasks led by the Black Belt, not Champion duties.","Statement 3 is wrong: the analysis is the Belt’s work; the Champion reviews the results at tollgates.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-997",phase:1,topic:"1.3.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

[?] is the gradual, unapproved expansion of a project beyond the boundaries agreed in its charter.`,options:["Gold plating","Rework","Scope creep","Sub-optimisation"],answer:2,hint:"Unapproved growth of the project boundaries.",steps:[{title:"Key idea",body:"**Scope creep** is many small, unapproved additions that together dilute effort and delay the finish."},{title:"Eliminate look-alikes",body:"Gold plating, rework and sub-optimisation are different project or process problems."}],final:"Unapproved boundary growth = scope creep → answer **C**",whyWrong:["Incorrect — gold plating is adding features nobody asked for to a deliverable, not growth of the project boundaries.","Incorrect — rework is repeating work that was not right first time.","","Incorrect — sub-optimisation is improving one part of a system at the expense of the whole."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-998",phase:1,topic:"1.3.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A goal statement that gives no completion date fails the [?] part of the SMART test.`,options:["Achievable","Measurable","Relevant","Time-bound"],answer:3,hint:"Which SMART letter is about a date?",steps:[{title:"Key idea",body:"SMART = Specific, Measurable, Achievable, Relevant, **Time-bound**."},{title:"Apply",body:"No completion date → the goal is not time-bound."}],final:"No date → not Time-bound → answer **D**",whyWrong:["Incorrect — Achievable is about whether the target is realistic for the resources.","Incorrect — Measurable is about having a number with a baseline and a target.","Incorrect — Relevant is about the goal supporting the business case.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-999",phase:1,topic:"1.3.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A [?] is a fixed limit the project must work within, such as “no new headcount and no capital spend”.`,options:["assumption","constraint","issue","risk"],answer:1,hint:"Fixed limit → respect it.",steps:[{title:"Key idea",body:"A **constraint** is a fixed boundary on resources or options: it is respected, not mitigated or tested."},{title:"Eliminate look-alikes",body:"Assumptions are checked, risks mitigated and issues resolved."}],final:"Fixed limit = constraint → answer **B**",whyWrong:["Incorrect — an assumption is something treated as true without proof, which must be checked.","","Incorrect — an issue is a problem that has already happened and needs resolving.","Incorrect — a risk is an uncertain event that might happen and needs mitigation."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1000",phase:1,topic:"1.3.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The business case usually carries an early estimate of the [?], which shows what the problem is costing the organisation.`,options:["COPQ","Cpk","DPMO","RPN"],answer:0,hint:"Cost of the problem → cost of poor quality.",steps:[{title:"Key idea",body:"The book’s Define roadmap includes “Estimate COPQ” (p. 230). The business case uses this early **cost of poor quality** estimate."},{title:"Eliminate look-alikes",body:"Cpk, DPMO and RPN are capability, defect-rate and risk measures, not costs."}],final:"Early cost estimate = COPQ → answer **A**",whyWrong:["","Incorrect — Cpk is a capability index calculated in Measure from process data and specifications.","Incorrect — DPMO is a defect rate per million opportunities, not a cost estimate.","Incorrect — RPN is the risk priority number from an FMEA."],bookRef:"Book p. 230"},{id:"sv-1-1001",phase:1,topic:"1.3.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The book glossary calls the goal statement an [?] statement: a short statement of the goals, timing and expectations of a project.`,options:["impact","mission","objective","vision"],answer:2,hint:"Glossary term for goals, timing and expectations.",steps:[{title:"Key idea",body:"Book glossary p. 587: an **objective statement** is a succinct statement of the goals, timing and expectations of the project."},{title:"Eliminate look-alikes",body:"Mission and vision are organisation-level statements; impact belongs to the problem statement."}],final:"Goal statement = objective statement → answer **C**",whyWrong:["Incorrect — impact is one element of the problem statement, not the name of the goal statement.","Incorrect — a mission statement describes an organisation’s purpose, not a project goal.","","Incorrect — a vision statement describes a long-term future state of an organisation."],bookRef:"Book p. 587"},{id:"sv-1-1002",phase:1,topic:"1.3.1",qtype:"missing-word",difficulty:3,stem:`Identify the missing word in the following sentence.

The book glossary describes breakthrough improvement as improvement at or near [?] over baseline.`,options:["30%","50%","70%","90%"],answer:2,hint:"Book p. 584: breakthrough ≈ seventy per cent.",steps:[{title:"Key idea",body:"Book glossary p. 584: **breakthrough improvement** is improvement at or near **70%** over baseline."},{title:"Use",body:"It is a yardstick for ambition: not every Black Belt goal must reach it, but tiny targets rarely justify DMAIC."}],final:"Breakthrough ≈ 70% over baseline → answer **C**",whyWrong:["Incorrect — 30% is well short of the glossary’s breakthrough level.","Incorrect — 50% is a large gain but below the glossary’s breakthrough level.","","Incorrect — 90% is higher than the level the glossary uses for breakthrough."],bookRef:"Book p. 584"},{id:"sv-1-1003",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:1,stem:"Which is NOT a question that a project’s **business case** should answer?",options:["Why must it be tackled now?","Which solution will the team implement?","What happens if we do nothing?","Why is this problem worth solving?"],answer:1,hint:"Why this, why now, cost of doing nothing, link to strategy.",steps:[{title:"Key idea",body:"The business case argues that the problem deserves resources now. It does not propose a fix."},{title:"Find the outsider",body:"Choosing the solution belongs to Improve, after the causes are verified."}],final:"Solution choice is not a business case question → answer **B**",whyWrong:["Incorrect — this IS a business case question: the urgency.","","Incorrect — this IS a business case question: the consequence of inaction.","Incorrect — this IS a business case question: the measurable pain."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1004",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a warning sign of a disguised solution in a problem statement?",options:["A stated time window such as “in Q2 2026”","A named tool, system or technology","A request for extra headcount","Phrases such as “we lack” or “we need to”"],answer:0,hint:"Warning signs: lack of, need to, named tool, headcount, “should implement”.",steps:[{title:"Key idea",body:"Disguised solutions contain the answer. Warning words: lack of, need to, insufficient, a named tool, extra headcount."},{title:"Find the outsider",body:"A time window is a required element (“when”) of a good problem statement."}],final:"A time window is a good element, not a warning sign → answer **A**",whyWrong:["","Incorrect — this IS a warning sign: naming a tool states the solution.","Incorrect — this IS a warning sign: more staff is a solution, not a measured gap.","Incorrect — this IS a warning sign: it frames the missing fix as the problem."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1005",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:2,stem:"Which is NOT normally a responsibility of the **Green Belt** leading a chartered project?",options:["Organising the collection of process data","Leading the team through the DMAIC phases","Signing the charter as the accountable sponsor","Presenting progress at each tollgate review"],answer:2,hint:"Belt leads and reports; Champion signs and is accountable.",steps:[{title:"Key idea",body:"The Black Belt leads the team, collects and analyses data and reports at tollgates."},{title:"Find the outsider",body:"Signing as the accountable sponsor is the Champion’s role."}],final:"Sponsor sign-off is the Champion’s job → answer **C**",whyWrong:["Incorrect — this IS a Green Belt responsibility: planning and leading data collection.","Incorrect — this IS a Green Belt responsibility: leading the project work.","","Incorrect — this IS a Green Belt responsibility: reporting to the Champion at tollgates."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1006",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:3,stem:"A Champion reviews a draft charter. Which finding would NOT be a sign of a weak charter?",options:["The problem statement names the preferred solution","The scope covers several processes, regions and products","The goal and problem statements use the same metric","The goal has no baseline or completion date"],answer:2,hint:"Common mistakes: solution in problem, goal with no baseline/date, different metrics, huge scope.",steps:[{title:"Key idea",body:"The usual charter mistakes include a goal without baseline or date, a solution in the problem, boil-the-ocean scope and mismatched metrics."},{title:"Find the outsider",body:"Using the same metric in problem and goal is good practice, not a weakness."}],final:"Same metric in both = good practice → answer **C**",whyWrong:["Incorrect — this IS a weakness: a disguised solution skips Measure and Analyze.","Incorrect — this IS a weakness: boil-the-ocean scope dilutes effort.","","Incorrect — this IS a weakness: the goal is neither measurable against a baseline nor time-bound."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1007",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a good source of evidence for a project’s business case?",options:["The Black Belt’s personal view of which solution would work best","The trend in SLA penalties paid over the last year","A regulator’s deadline for meeting a service standard","Customer complaint data about the problem"],answer:0,hint:"Business case = evidence of pain and urgency, not solution opinions.",steps:[{title:"Key idea",body:"A business case is evidence-based: VOC and VOB data, trends, deadlines and the cost of inaction."},{title:"Find the outsider",body:"A personal preference for a solution is neither evidence nor part of the business case."}],final:"Solution opinion is not evidence → answer **A**",whyWrong:["","Incorrect — this IS good evidence: Voice of the Business data show the cost.","Incorrect — this IS good evidence: a deadline explains why now.","Incorrect — this IS good evidence: Voice of the Customer data show the pain."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1008",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the letters of a **SMART** goal?",options:["Specific","Sustainable","Relevant","Measurable"],answer:1,hint:"Specific, Measurable, Achievable, Relevant, Time-bound.",steps:[{title:"Key idea",body:"SMART = Specific, Measurable, Achievable, Relevant, Time-bound."},{title:"Find the outsider",body:"Sustaining results is the aim of Control, but “Sustainable” is not a SMART letter."}],final:"Sustainable is not a SMART letter → answer **B**",whyWrong:["Incorrect — Specific IS a SMART letter: one clearly named metric and population.","","Incorrect — Relevant IS a SMART letter: the goal supports the business case.","Incorrect — Measurable IS a SMART letter: a number with baseline and target."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1009",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:1,stem:"A charter lists four items under *Constraints*. Which item is NOT a constraint?",options:["The vendor contract cannot change before renewal","No capital spend is available this year","The vendor may not release ticket data in time","No new headcount may be added"],answer:2,hint:"Constraint = fixed limit; risk = uncertain event (“may”).",steps:[{title:"Key idea",body:"Constraints are fixed limits the project must respect."},{title:"Find the outsider",body:"“May not release data in time” is uncertain — it is a **risk**, which needs a mitigation plan."}],final:"An uncertain “may” event is a risk → answer **C**",whyWrong:["Incorrect — this IS a constraint: a fixed limit on options.","Incorrect — this IS a constraint: a fixed limit on budget.","","Incorrect — this IS a constraint: a fixed limit on resources."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1010",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:1,stem:"A NOC manager drafts this problem statement: *“The NOC needs an AI-based monitoring tool to stop outages.”* What is the main weakness?",options:["It states a verified root cause of the outages","It is correct, because it explains clearly what the team must do","It is a disguised solution: it names a tool instead of describing a measured gap","It blames the NOC engineers for the outages"],answer:2,hint:"Named tool + “needs” → disguised solution.",steps:[{title:"Key idea",body:"Warning signs of a disguised solution: “need to”, a named tool or technology."},{title:"Apply",body:"The draft has no what/where/when/how big; it simply requests a tool."}],final:"Named tool → disguised solution → answer **C**",whyWrong:["Incorrect — no cause is stated or verified; the draft jumps straight to a solution.","Incorrect — saying what to do is exactly the fault: the problem statement must describe the gap, not the action.","","Incorrect — no person is blamed; the draft names a fix."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1011",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:3,stem:"A Black Belt drafts four problem statements for a late supplier-payment project. Which is the BEST problem statement?",options:["“Supplier payments are often late and Finance is unhappy about it.”","“We need two more invoice clerks to stop paying suppliers late.”","“In FY2025, 9% of supplier invoices were paid after the due date, costing OMR 27,000 in late-payment charges.”","“In FY2025, 9% of supplier invoices were paid late because the approval workflow is too slow.”"],answer:2,hint:"What, where, when, how big, impact — and no cause, solution or blame.",steps:[{title:"Key idea",body:"The best statement is quantified and bounded, and contains no cause, no solution and no blame."},{title:"Eliminate",body:"One adds a cause, one proposes headcount and one is vague. Only one gives time frame, size and impact with nothing extra."}],final:"Quantified, bounded, no cause or solution → answer **C**",whyWrong:["Incorrect — it is vague: no size, no time frame and no measurable impact.","Incorrect — extra headcount is a disguised solution, and nothing is quantified.","","Incorrect — it is quantified but states an unverified cause (“because…”)."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1012",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:2,stem:"A sponsor tells a Black Belt, *“Just make complaints go down.”* The draft goal reads: *“Reduce customer complaints.”* Which SMART elements are clearly missing?",options:["Specific and Relevant — complaints are unrelated to the business","None — the goal is acceptable because the direction is clear","Achievable only — the goal is too ambitious","Measurable and Time-bound — there is no target value and no date"],answer:3,hint:"Check each letter: is there a number? a date?",steps:[{title:"Key idea",body:"A SMART goal needs a baseline and target (Measurable) and a completion date (Time-bound)."},{title:"Apply",body:"“Reduce complaints” gives a direction but no number and no date."}],final:"No target, no date → not Measurable, not Time-bound → answer **D**",whyWrong:["Incorrect — complaints are relevant to the business; the gaps are the missing number and date.","Incorrect — a direction alone cannot be measured or completed by a date.","Incorrect — with no target value there is nothing to judge as too ambitious.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1013",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:2,stem:"A charter line reads: *“Enterprise incidents in the Northern region, from incident logging to restoration confirmation; consumer incidents excluded.”* Which charter element is this?",options:["Business case","Scope","Problem statement","Goal statement"],answer:1,hint:"Start point, end point, in / out → scope.",steps:[{title:"Key idea",body:"Scope defines the process start and end points and what is in and out."},{title:"Apply",body:"The line names a start (logging), an end (restoration confirmation) and an exclusion — scope."}],final:"Boundaries + exclusion = scope → answer **B**",whyWrong:["Incorrect — a business case argues why the problem matters now.","","Incorrect — a problem statement gives a measured gap and its impact, not process boundaries.","Incorrect — a goal statement gives a target and a date."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1014",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:3,stem:"A problem statement reads: *“In the last 6 months, 14% of fibre repairs in the Eastern zone needed a repeat visit within 7 days.”* Which element of the five-part model is missing?",options:["The where — the zone in which the problem occurs","The how big — the size of the gap","The when — the time window of the data","The impact — the cost or customer effect of the repeat visits"],answer:3,hint:"What, where, when, how big, impact.",steps:[{title:"Check each element",body:"What: repeat visits within 7 days. Where: Eastern zone. When: last 6 months. How big: 14%."},{title:"Find the gap",body:"Nothing says what the repeat visits cost or how they affect customers — the impact is missing."}],final:"Missing element = impact → answer **D**",whyWrong:["Incorrect — “Eastern zone” gives the where.","Incorrect — “14%” gives the size of the gap.","Incorrect — “in the last 6 months” gives the when.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1015",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:2,stem:"A Black Belt is writing the “why now” part of a business case for an SLA-breach project. Which fact strengthens it most?",options:["Two of the five largest enterprise accounts renew next year and have raised restoration times in reviews","A vendor has offered a new monitoring tool at a discount","The Black Belt has free time in the next quarter","The SLA breach process was first documented five years ago"],answer:0,hint:"Why now = a trigger: renewal, deadline, rising trend.",steps:[{title:"Key idea",body:"Urgency comes from a trigger such as a contract renewal, a regulatory deadline or a rising trend."},{title:"Apply",body:"Upcoming renewals of large accounts that already complain make the problem urgent."}],final:"Renewal at risk = why now → answer **A**",whyWrong:["","Incorrect — a discounted tool is a possible solution, not a reason the problem is urgent.","Incorrect — team availability is a resource fact, not evidence of business urgency.","Incorrect — an old document date shows no urgency for acting now."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1016",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:2,stem:"A moulding-plant charter goal reads: *“Reduce changeover time on Press 2 from 50 to 20 minutes by December 2026, **without increasing scrap**.”* What is the role of the final clause?",options:["It names the solution the team will implement","It states the root cause of the long changeovers","It protects a guard-rail metric so the improvement does not damage another result","It defines the process start and end points"],answer:2,hint:"Goal = primary metric + guard-rail (secondary) metric.",steps:[{title:"Key idea",body:"A goal can name a guard-rail (secondary) metric that must not get worse while the primary metric improves."},{title:"Apply",body:"Faster changeovers must not be bought with more scrap."}],final:"Final clause = guard-rail metric → answer **C**",whyWrong:["Incorrect — the clause says what must not get worse, not how to improve.","Incorrect — scrap is not given as a cause; the clause limits side effects.","","Incorrect — start and end points belong to the scope section."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1017",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:3,stem:"A charter goal for router dead-on-arrival returns reads: *“Reduce DOA returns from 4.0% to 3.9% by June 2027.”* What is the main concern?",options:["The goal has no completion date","The goal uses a different metric from the problem","The goal names the method of improvement","The target is so small that it probably does not justify a DMAIC project"],answer:3,hint:"Breakthrough ≈ 70% over baseline; a tiny target rarely justifies DMAIC.",steps:[{title:"Key idea",body:"The book uses ~70% over baseline as breakthrough. Not every project must reach it, but a trivial target rarely justifies DMAIC effort."},{title:"Apply",body:"A move from 4.0% to 3.9% is a very small improvement for a full project."}],final:"Target too small for DMAIC → answer **D**",whyWrong:["Incorrect — “by June 2027” is a completion date.","Incorrect — DOA returns is the metric in both; the issue is the size of the target.","Incorrect — no method is named; the concern is ambition.",""],bookRef:"Book p. 584"},{id:"sv-1-1018",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:2,stem:"A Black Belt charter for scrap on Line 4 names: the Black Belt, two operators, a maintenance technician and a quality engineer, with the plant manager as Champion. The line’s production supervisor, who will run the improved process, is not named. Which role is missing?",options:["Master Black Belt","Subject-matter expert","Process owner","Champion"],answer:2,hint:"Who will run and sustain the improved process?",steps:[{title:"Key idea",body:"The process owner manages the process day to day and must accept it at hand-over."},{title:"Apply",body:"The production supervisor fits that role but is not on the charter."}],final:"Missing role = process owner → answer **C**",whyWrong:["Incorrect — a coach may help, but the person who will run the improved process is the process owner.","Incorrect — the maintenance technician and quality engineer already supply specialist knowledge.","","Incorrect — the plant manager is already named as Champion."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1019",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:3,stem:"A problem statement reads: *“In Q1, 22% of audited incidents had a priority that did not match the impact criteria.”* The Champion asks to add *“because the vendor’s engineers are careless.”* What is the BEST response?",options:["Keep the clause out, because it blames people and asserts a cause that has not been verified","Add the clause, because the Champion owns the charter","Remove the 22% figure so the statement is less critical of the vendor","Add the clause, but move it to the goal statement"],answer:0,hint:"No cause, no solution, no blame.",steps:[{title:"Key idea",body:"The problem statement describes the gap in data terms. “Careless engineers” is both blame and an unverified cause."},{title:"Apply",body:"The Black Belt should explain that the cause will be investigated in Analyze and keep the statement neutral."}],final:"Keep blame and causes out → answer **A**",whyWrong:["","Incorrect — owning the charter does not make an unverified, blaming cause acceptable.","Incorrect — the measured gap is the essential part; it is the blame that must go.","Incorrect — causes and blame do not belong in the goal statement either."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1020",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:2,stem:"A sponsor tells a Black Belt: *“Implement robotic process automation for invoice matching.”* No data on the matching problem exist yet. What is the FIRST action?",options:["Start building the automation so the sponsor sees quick progress","Ask Finance to confirm the savings from automation","Write the charter goal as “Implement RPA by June”","Collect data on the invoice-matching gap and write a problem statement that describes it"],answer:3,hint:"Turn a requested solution back into a measured problem.",steps:[{title:"Key idea",body:"A request for a solution should be reframed: what gap is it meant to close, and how big is it?"},{title:"Apply",body:"Quantify the matching problem first; the solution, if any, comes from Analyze and Improve."}],final:"Reframe the request as a measured problem → answer **D**",whyWrong:["Incorrect — building a pre-chosen fix skips Measure and Analyze; the real cause may be different.","Incorrect — savings cannot be validated before the problem is even measured.","Incorrect — a goal that names the method is a disguised solution.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1021",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:3,stem:"While drafting a charter, a Black Belt finds the problem spans five departments and three product lines and would take about two years. She proposes splitting it into three smaller projects, each with its own charter. Was this an appropriate action?",options:["No, because one large project always delivers more benefit than several small ones","No, because the scope can only be changed after the Measure phase","Yes, because a project too big for a one-page charter should be broken into manageable, bounded projects","Yes, because every project must be limited to one department"],answer:2,hint:"Too big for one page → split into bounded projects.",steps:[{title:"Key idea",body:"If a project cannot fit on a one-page charter, it is probably too big. Boil-the-ocean scope is a common charter mistake."},{title:"Apply",body:"Splitting into bounded projects with their own charters keeps each one focused and achievable."}],final:"Split an oversized project → appropriate → answer **C**",whyWrong:["Incorrect — boil-the-ocean projects dilute effort and often stall; focused projects finish and deliver.","Incorrect — scope is set in Define; resizing before sign-off is exactly when it should happen.","","Incorrect — cross-functional projects are allowed; the issue is size and focus, not the number of departments."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1022",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:3,stem:"At the Analyze tollgate, the Black Belt shows that a key cause sits in a process listed as out of scope. She presents the impact on the timeline, and the Champion approves adding it; the charter is re-issued as version 2 with a new end date. Was this an appropriate action?",options:["No, because a signed charter can never be changed","Yes, because the scope change was a formal Champion decision recorded in a new charter version","Yes, because the Black Belt may expand scope whenever a cause is found","No, because out-of-scope processes must always be handed to another team"],answer:1,hint:"Scope changes are allowed when formally approved and recorded.",steps:[{title:"Key idea",body:"Scope creep is **unapproved** growth. A change assessed for impact, approved by the Champion and recorded in a new version is controlled change."},{title:"Apply",body:"Every step here was formal and documented."}],final:"Formal, recorded change → appropriate → answer **B**",whyWrong:["Incorrect — the charter is a living document; formal, recorded changes are allowed.","","Incorrect — the Belt cannot change scope alone; it was appropriate only because the Champion approved it.","Incorrect — handing over is one option, but a formal Champion decision to add scope is also valid."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1023",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:3,stem:"Measure data show that 80% of late restorations come from one region, although the charter covers all four regions. What is the BEST action?",options:["Propose narrowing the scope and updating the problem statement at the tollgate, with the Champion’s agreement","Keep the original scope, because a signed charter must not change","Close the project, because the problem is smaller than expected","Quietly drop the other three regions from the data collection"],answer:0,hint:"New facts → open, agreed charter update at a tollgate.",steps:[{title:"Key idea",body:"The book’s Measure checklist asks “Has the Problem Statement changed?” (p. 231). Charters are updated openly at tollgates."},{title:"Apply",body:"Focusing on the region that drives 80% of the problem should be proposed and approved, not done silently."}],final:"Update the charter openly with the Champion → answer **A**",whyWrong:["","Incorrect — the charter is a living document and should reflect new facts.","Incorrect — the problem is concentrated, not small; focusing the project makes it more effective.","Incorrect — silent changes to scope are exactly what the living-charter rule forbids."],bookRef:"Book p. 231"},{id:"sv-1-1024",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:2,stem:"The Head of Billing asks a new Green Belt to start a project on *“improving billing”*. No figures are available. What is the FIRST action?",options:["Set a goal of a 50% improvement by year end","Gather baseline data to find and quantify the specific billing gap","Write the problem statement as “Billing needs to improve”","Run a brainstorm of solutions with the billing team"],answer:1,hint:"A problem statement needs data: what, where, when, how big.",steps:[{title:"Key idea",body:"A charter needs a bounded, quantified problem. Without data, neither the problem nor the goal can be written."},{title:"Apply",body:"Collect baseline data first to find which billing defect matters and how big it is."}],final:"Quantify the gap first → answer **B**",whyWrong:["Incorrect — a target cannot be set without a defined metric and baseline.","","Incorrect — this is vague: no what, where, when or how big.","Incorrect — solutions come after the problem is measured and the causes verified."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1025",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:2,stem:"The Champion says the out-of-scope list is unnecessary because *“everyone knows what we are not doing.”* The Black Belt keeps it in the charter. Was this an appropriate action?",options:["No, because out-of-scope items are recorded only in the control plan","Yes, because the out-of-scope list replaces the need for an in-scope list","No, because the Champion decides the charter content and the list should go","Yes, because an explicit out-of-scope list protects the project against scope creep"],answer:3,hint:"Explicit boundaries are the first defence against creep.",steps:[{title:"Key idea",body:"Writing down what is out of scope makes later “could you also…” requests visible as scope changes."},{title:"Apply",body:"Keeping the list was the right call; “everyone knows” assumptions are how creep starts."}],final:"Explicit out-of-scope list → appropriate → answer **D**",whyWrong:["Incorrect — scope boundaries belong in the charter, not the Control-phase control plan.","Incorrect — both lists are needed; one does not replace the other.","Incorrect — the Belt should explain why the list matters; it is standard charter content.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1026",phase:1,topic:"1.3.1",qtype:"best-action",difficulty:3,stem:"In Define, a Black Belt writes in the charter: *“Benefits: OMR 250,000 annual savings (confirmed).”* No data have yet been validated. Was this an appropriate action?",options:["Yes, because benefits are confirmed when the Champion signs the charter","No, because benefits must never appear in a charter","No, because Define benefits are preliminary estimates that must be validated with Finance","Yes, because a confident benefit figure helps the charter get approved"],answer:2,hint:"Define benefits = estimated, not confirmed.",steps:[{title:"Key idea",body:"Preliminary benefits are estimates refined in Measure and validated with Finance before anyone claims them."},{title:"Apply",body:"Writing “confirmed” before validation states benefits as fact too early."}],final:"Label benefits as estimates → answer **C**",whyWrong:["Incorrect — a signature does not validate savings; Finance validates them with data.","Incorrect — preliminary benefits are a normal charter element; they must be labelled as estimates.","","Incorrect — presenting estimates as fact misleads the Champion and is a common charter mistake."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1027",phase:1,topic:"1.3.1",qtype:"output",difficulty:2,stem:`A Black Belt runs a cross-tabulation for the problem statement:

\`\`\`
Tabulated Statistics: Region, SLA status
Q2 2026, P1/P2 enterprise incidents

         Late   On time     All
North     225     1,025   1,250
South      48       752     800
East       31       569     600
All       304     2,346   2,650

Late % by row:  North 18.0   South 6.0   East 5.2
\`\`\`

Which problem statement is BEST supported by the output?`,options:["“In Q2 2026, the North had 18% late restorations because its engineers are slower.”","“In Q2 2026, 225 of 1,250 P1/P2 enterprise incidents in the North (18%) were restored after the SLA.”","“In Q2 2026, 304 P1/P2 enterprise incidents in the North were restored after the SLA.”","“In Q2 2026, 18% of P1/P2 enterprise incidents in all regions were restored after the SLA.”"],answer:1,hint:"Read the right row and column; keep causes out.",steps:[{title:"Read the output",body:"North row: 225 late of 1,250, late % = 18.0."},{title:"Apply the rules",body:"The best statement quotes the North figures correctly, with a time window and no cause."}],final:"North: 225 of 1,250 (18%), no cause → answer **B**",whyWrong:["Incorrect — the numbers are right but “because its engineers are slower” adds an unverified cause and blame.","","Incorrect — 304 is the total for all regions, not the North.","Incorrect — 18.0% is the North row only, not all regions."],bookRef:"Book p. 587"},{id:"sv-1-1028",phase:1,topic:"1.3.1",qtype:"output",difficulty:3,stem:`A Black Belt summarises the baseline for a ticket-assignment project:

\`\`\`
Descriptive Statistics: Assignment wait (min), P2 tickets
Period: Jan-Jun 2026

   N    Mean   Median     Q3   %>45 min
3200   52.4     38.0   71.0       31.0

Target: first assignment within 15 min
\`\`\`

The problem statement uses the “% of P2 tickets waiting more than 45 minutes”. Which goal statement is consistent with it?`,options:["“Implement automatic ticket routing for P2 tickets by 30 June 2027.”","“Reduce the average handling time of P2 tickets by 20% by 30 June 2027.”","“Reduce the share of P2 tickets waiting more than 45 minutes for assignment from 31% to 10% by 30 June 2027.”","“Raise customer satisfaction with P2 tickets to 90% by 30 June 2027.”"],answer:2,hint:"Goal = same metric as the problem + target + date.",steps:[{title:"Read the output",body:"The baseline metric is **%>45 min = 31.0%**."},{title:"Apply",body:"Only one goal uses that same metric, with a target and a date; the others change the metric or name a method."}],final:"Same metric (31% → target) + date → answer **C**",whyWrong:["Incorrect — this names a method (a disguised solution) and gives no measurable target.","Incorrect — handling time is a different metric from the assignment-wait baseline.","","Incorrect — satisfaction is a different metric, so success cannot be judged against the 31% baseline."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1029",phase:1,topic:"1.3.1",qtype:"output",difficulty:3,stem:`A Champion reviews the goal check for a charter:

\`\`\`
Goal check - PRJ-207 (late restorations, North)
Baseline (Q2 2026)          18.0 %
Target (31 Mar 2027)         6.0 %
Reduction                   12.0 percentage points
Improvement vs baseline     66.7 %
\`\`\`

Which statement about this goal is CORRECT?`,options:["It is too small for DMAIC, because the reduction is only 12 points","It cannot be called breakthrough, because breakthrough means 100% elimination","It is a 12% improvement over baseline","It is a 66.7% improvement over baseline, close to the book’s breakthrough level"],answer:3,hint:"Percentage points ≠ percent improvement; breakthrough ≈ 70%.",steps:[{title:"Read the output",body:"The reduction is **12.0 percentage points**; the improvement vs baseline is **66.7%**."},{title:"Apply",body:"Book p. 584: breakthrough is at or near 70% over baseline, so 66.7% is close to it."}],final:"66.7% improvement ≈ breakthrough level → answer **D**",whyWrong:["Incorrect — a two-thirds cut in late restorations is an ambitious target.","Incorrect — the glossary puts breakthrough at or near 70% over baseline, not 100%.","Incorrect — 12.0 is the reduction in percentage points; the improvement over baseline is printed as 66.7%.",""],trap:"Do not confuse percentage points with percent improvement.",bookRef:"Book p. 584"},{id:"sv-1-1030",phase:1,topic:"1.3.1",qtype:"output",difficulty:2,stem:`A charter template tool prints this completeness check before the Define tollgate:

\`\`\`
Charter completeness check - PRJ-114
Element               Status
Business case         Complete
Problem statement     Complete
Goal statement        Missing completion date
Scope (in/out)        In-scope list only
Team / roles          Complete
Champion sign-off     Pending
\`\`\`

Which conclusion is correct?`,options:["The missing date can stay in the milestones, so the goal is acceptable","The charter can be signed now, because the business case is complete","Only the Champion signature is missing, so the team can start Measure","The goal is not time-bound and the scope has no out-of-scope list, so the charter is not ready"],answer:3,hint:"Every block complete before the Champion signs.",steps:[{title:"Read the output",body:"Two gaps: goal has **no completion date**; scope shows **in-scope only**."},{title:"Apply",body:"A goal without a date is not time-bound, and a missing out-of-scope list invites scope creep. Fix both before sign-off."}],final:"Goal undated + no out-of-scope list → not ready → answer **D**",whyWrong:["Incorrect — a goal without a completion date fails the Time-bound test.","Incorrect — the goal has no date and the out-of-scope list is missing.","Incorrect — the goal and scope gaps must be fixed before signature.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1031",phase:1,topic:"1.3.1",qtype:"output",difficulty:3,stem:`A project office prints the version log for a charter:

\`\`\`
Charter version log - PRJ-114
Version  Date        Change                              Approved by
1.0      02-Mar-26   Original charter signed             Champion
1.1      14-Apr-26   Scope narrowed to North region      Champion
1.2      20-May-26   Collections letters added to scope  (none)
\`\`\`

Which conclusion is correct?`,options:["Version 1.2 is scope creep, because the scope was enlarged without the Champion’s approval","Version 1.2 is acceptable, because the change was recorded in the log","The charter should never have changed after version 1.0","Version 1.1 is scope creep, because the scope changed after the charter was signed"],answer:0,hint:"Scope creep = unapproved growth; approved and recorded = controlled change.",steps:[{title:"Read the output",body:"1.1 narrowed scope with Champion approval. 1.2 **added** scope with **no** approval."},{title:"Apply",body:"Unapproved growth beyond the charter is scope creep."}],final:"Unapproved addition in 1.2 = scope creep → answer **A**",whyWrong:["","Incorrect — recording is not enough; scope changes need the Champion’s approval.","Incorrect — the charter is a living document; approved, recorded changes are allowed.","Incorrect — 1.1 was approved by the Champion, so it is a controlled change."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1032",phase:1,topic:"1.3.1",qtype:"output",difficulty:2,stem:`A deployment lead tallies why charters were sent back at Define tollgates last year:

\`\`\`
Tally for Discrete Variables: Rejection reason

Rejection reason                    Count  Percent
Solution or cause in problem stmt     14     43.8
Goal has no baseline or date           9     28.1
Scope too wide                         6     18.8
No Champion signature                  3      9.4
N=                                    32
\`\`\`

Which change to the charter template would address the largest category?`,options:["Add a check that the goal has a baseline and a completion date","Add a mandatory Champion signature box","Add a check that the problem statement contains no cause and no solution","Add a check that the scope has explicit in and out lists"],answer:2,hint:"Read the largest count, then match the fix to it.",steps:[{title:"Read the output",body:"The largest category is **Solution or cause in problem stmt — 14 (43.8%)**."},{title:"Apply",body:"The matching fix is a template check for causes and solutions in the problem statement."}],final:"Largest reason → check problem statement wording → answer **C**",whyWrong:["Incorrect — that addresses the second category (28.1%), not the largest.","Incorrect — missing signatures are the smallest category (9.4%).","","Incorrect — that addresses “scope too wide” (18.8%), not the largest category."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1033",phase:1,topic:"1.3.1",qtype:"true-false",difficulty:1,stem:"A problem statement should describe the gap in measurable terms without stating its cause. True or False?",options:["True","False"],answer:0,hint:"No cause, no solution, no blame.",steps:[{title:"Key idea",body:"The problem statement bounds and describes the gap (book p. 587)."},{title:"Apply",body:"Measurable terms are required; a cause is excluded until Analyze verifies it — so the statement is true."}],final:"Measurable, no cause → answer **A** (True)",whyWrong:["","Incorrect — the statement is true: causes are verified in Analyze and do not belong in the problem statement."],bookRef:"Book p. 587"},{id:"sv-1-1034",phase:1,topic:"1.3.1",qtype:"true-false",difficulty:1,stem:"A project charter normally runs to several pages so that every project task can be planned in it. True or False?",options:["True","False"],answer:1,hint:"One page is a feature of the charter.",steps:[{title:"Key idea",body:"A charter is normally one page. If the project cannot fit on one page, it is probably too big or not understood."},{title:"Apply",body:"Detailed task planning belongs to the project plan, so the statement is false."}],final:"Charter = one page → answer **B** (False)",whyWrong:["Incorrect — the statement is false: a charter is normally one page; task planning belongs in the project plan.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1035",phase:1,topic:"1.3.1",qtype:"true-false",difficulty:2,stem:"Scope creep is any change to the project scope that the Champion has formally approved. True or False?",options:["True","False"],answer:1,hint:"Creep = unapproved.",steps:[{title:"Key idea",body:"Scope creep is the gradual, **unapproved** expansion of a project."},{title:"Apply",body:"A formally approved, recorded change is the opposite of creep, so the statement is false."}],final:"Approved change ≠ scope creep → answer **B** (False)",whyWrong:["Incorrect — the statement is false: scope creep is unapproved growth; formally approved changes are controlled change.",""],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1036",phase:1,topic:"1.3.1",qtype:"true-false",difficulty:1,stem:"A business case should explain what is likely to happen if the organisation does nothing about the problem. True or False?",options:["True","False"],answer:0,hint:"Why this, why now, cost of doing nothing, link to strategy.",steps:[{title:"Key idea",body:"A business case answers four questions, including “What happens if we do nothing?”."},{title:"Apply",body:"Penalties growing, customers leaving or backlogs rising are the consequences it should state — so the statement is true."}],final:"Cost of inaction belongs in the business case → answer **A** (True)",whyWrong:["","Incorrect — the statement is true: the cost of inaction is one of the four questions a business case answers."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1037",phase:1,topic:"1.3.1",qtype:"sequence",difficulty:2,stem:`A senior manager asks a Black Belt to add a second process to her chartered project. In which order should she handle the request?

- **P** The Champion decides whether to accept the change
- **Q** Record the decision in a new charter version
- **R** Assess the impact on the goal, timeline and resources
- **S** Present the request and its impact to the Champion`,options:["P → R → S → Q","S → R → P → Q","R → S → P → Q","R → P → S → Q"],answer:2,hint:"Assess → present → decide → record.",steps:[{title:"Key idea",body:"Any scope change is a formal Champion decision recorded in a new charter version."},{title:"Order",body:"Assess impact (R), present it (S), Champion decides (P), record the new version (Q)."}],final:"Assess → present → decide → record = R → S → P → Q → answer **C**",whyWrong:["Incorrect — the Champion cannot decide before the impact is assessed and presented.","Incorrect — the impact must be assessed before the request is presented, so the Champion can decide on facts.","","Incorrect — the Champion decides after the request and its impact have been presented."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1038",phase:1,topic:"1.3.1",qtype:"sequence",difficulty:3,stem:`Put these points in the life of a project charter in the order they normally occur.

- **P** Results are checked against the requirements of the business case
- **Q** The charter is drafted and signed by the Champion
- **R** The team asks whether the problem statement has changed after baseline data are collected
- **S** The charter is reviewed again after root causes are verified`,options:["Q → R → S → P","R → Q → S → P","Q → S → R → P","Q → R → P → S"],answer:0,hint:"Define → Measure → Analyze → Control.",steps:[{title:"Key idea",body:"The charter is a living document reviewed at each tollgate."},{title:"Order",body:"Drafted and signed in Define (Q); Measure checklist asks if the problem statement changed (R, p. 231); reviewed after Analyze (S); Control checks results against the business case (P, p. 578)."}],final:"Define → Measure → Analyze → Control = Q → R → S → P → answer **A**",whyWrong:["","Incorrect — baseline data are collected after the charter is drafted and signed in Define.","Incorrect — the baseline check (Measure) comes before root causes are verified (Analyze).","Incorrect — results are checked against the business case in Control, the last phase."],bookRef:"Book p. 231"},{id:"sv-1-1039",phase:1,topic:"1.3.1",qtype:"sequence",difficulty:2,stem:`A draft problem statement reads *“We need a chatbot to cut repeat calls.”* In which order should the Black Belt rewrite it?

- **P** Ask what symptom the proposed solution is meant to fix
- **Q** Spot the solution words in the draft
- **R** Rewrite the statement as a measured gap with time frame and impact
- **S** Gather data on the size of that symptom`,options:["Q → S → P → R","P → Q → S → R","Q → P → S → R","S → Q → P → R"],answer:2,hint:"Spot the fix → find the symptom → measure it → rewrite.",steps:[{title:"Key idea",body:"A disguised solution is fixed by working back from the solution to the symptom it targets."},{title:"Order",body:"Spot “need a chatbot” (Q), identify the symptom — repeat calls (P), measure it (S), rewrite as a gap (R)."}],final:"Spot → symptom → measure → rewrite = Q → P → S → R → answer **C**",whyWrong:["Incorrect — the symptom must be identified before data on its size can be gathered.","Incorrect — the solution words must be spotted first; that is what shows the draft needs reframing.","","Incorrect — data cannot be gathered before the team knows which symptom to measure."],bookRef:"Syllabus 1.3.1"},{id:"sv-1-1040",phase:1,topic:"1.3.1",qtype:"sequence",difficulty:2,stem:`To state the “how big” part of a problem statement, in which order should a Black Belt work?

- **P** Agree an operational definition of the defect
- **Q** Write the rate into the problem statement
- **R** Collect the data for the chosen time window
- **S** Count defects and units for the agreed time window`,options:["R → S → P → Q","R → P → S → Q","P → S → R → Q","P → R → S → Q"],answer:3,hint:"Define → collect → count → state.",steps:[{title:"Key idea",body:"A credible size needs a clear definition of the defect before any data are gathered."},{title:"Order",body:"Define the defect (P), collect the data (R), count (S), write the rate (Q)."}],final:"Define → collect → count → state = P → R → S → Q → answer **D**",whyWrong:["Incorrect — defining the defect after counting means the counts used no agreed rule.","Incorrect — the defect must be defined before data are collected, or the counts will be inconsistent.","Incorrect — defects cannot be counted before the data are collected.",""],bookRef:"Syllabus 1.3.1"}];export{e as items};
